/**
 * Archived locks. Once a cycle is over the Scorecard is served from files, so the site keeps
 * working without the database: data/archive/<lock>.json holds the frozen projections (written by
 * `pnpm archive`) and <lock>-results.csv the results (regenerated by `pnpm archive --results-only`,
 * or edited by hand). Push to redeploy with new results.
 */
import fs from "node:fs/promises";
import path from "node:path";
import { buildScorecard, lockCsvText, type LockedForecast } from "./scorecard";
import type { WatchPick } from "./watch";

export const ARCHIVE_DIR = path.join(process.cwd(), "data", "archive");

export interface ArchivedLock {
  lock: { id: string; asOf: string };
  watch: WatchPick[];
  races: { key: string; office: string; state: string | null; title: string }[];
  /** Pollster → lean (D | R | N) at lock time, for the pollster leaderboard. */
  leans: Record<string, string | null>;
  forecasts: LockedForecast[];
}

export interface ArchivedResult {
  winnerParty: string | null;
  demPct: number | null;
  repPct: number | null;
  calledAt: string | null;
  /** `market:<platforms>` from settlement; anything else is a hand edit and survives regeneration. */
  source: string | null;
}

const RESULT_COLS = ["race_key", "winner_party", "dem_pct", "rep_pct", "called_at", "source"];

export function parseResults(csv: string) {
  const out = new Map<string, ArchivedResult>();
  const [header, ...lines] = csv.trim().split(/\r?\n/);
  if (!header) return out;
  const cols = header.split(",").map((c) => c.trim());
  const num = (x: string | null) => (x == null ? null : Number(x));
  for (const line of lines) {
    if (!line.trim() || line.startsWith("#")) continue;
    const v = Object.fromEntries(line.split(",").map((x, i) => [cols[i], x.trim() || null]));
    if (!v.race_key) continue;
    out.set(v.race_key, { winnerParty: v.winner_party, demPct: num(v.dem_pct), repPct: num(v.rep_pct), calledAt: v.called_at, source: v.source });
  }
  return out;
}

export function resultsCsv(results: Map<string, ArchivedResult>) {
  const rows = [...results]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([key, r]) => [key, r.winnerParty, r.demPct, r.repPct, r.calledAt, r.source].map((x) => x ?? "").join(","));
  return [RESULT_COLS.join(","), ...rows].join("\n") + "\n";
}

/** One race / forecast per line, so diffs stay readable. */
export function archiveJson(a: ArchivedLock) {
  const list = (xs: unknown[]) => `[\n${xs.map((x) => `    ${JSON.stringify(x)}`).join(",\n")}\n  ]`;
  return `{\n  "lock": ${JSON.stringify(a.lock)},\n  "watch": ${list(a.watch)},\n  "races": ${list(a.races)},\n  "leans": ${JSON.stringify(a.leans)},\n  "forecasts": ${list(a.forecasts)}\n}\n`;
}

async function loadArchive(lockId: string) {
  if (!/^[\w-]+$/.test(lockId)) return null;
  const json = await fs.readFile(path.join(ARCHIVE_DIR, `${lockId}.json`), "utf8").catch(() => null);
  if (json == null) return null;
  const archive = JSON.parse(json) as ArchivedLock;
  const results = parseResults(await fs.readFile(path.join(ARCHIVE_DIR, `${lockId}-results.csv`), "utf8").catch(() => ""));
  const races = new Map(
    archive.races.map((r) => {
      const x = results.get(r.key);
      return [
        r.key,
        { ...r, winnerParty: x?.winnerParty ?? null, demPct: x?.demPct ?? null, repPct: x?.repPct ?? null, calledAt: x?.calledAt ?? null, resultSource: x?.source ?? null },
      ];
    }),
  );
  return { ...archive, races };
}

/** Scorecard data for an archived lock, or null if `lockId` isn't archived. */
export async function archivedScorecard(lockId: string) {
  const a = await loadArchive(lockId);
  if (!a) return null;
  return buildScorecard({
    lock: { id: a.lock.id, asOf: new Date(a.lock.asOf), preview: false, archived: true },
    forecasts: a.forecasts,
    races: [...a.races.values()],
    leanOf: (name) => a.leans[name] ?? null,
    watch: a.watch,
  });
}

export async function archivedCsv(lockId: string) {
  const a = await loadArchive(lockId);
  return a && lockCsvText({ lockId: a.lock.id, asOf: a.lock.asOf, watch: a.watch, forecasts: a.forecasts, races: a.races });
}
